/* Verse Games: THE WHOLE COUNSEL · Acts chapters 6-10
   Verse text is filled/verified from the KJV by tools/fill-verses.js */
VG.registerBibleChapters("acts", [
{n:6, name:"The Seven Chosen", seal:{ref:"Acts 6:4",verse:"But we will give ourselves continually to prayer, and to the ministry of the word."},
 facts:["Did you know the first church crisis was over widows' meals, and the apostles solved it by letting the congregation choose seven Spirit-filled men to serve the tables (Acts 6:1-3)?","Did you know Stephen was appointed to serve tables, yet he ended up 'full of faith and power,' doing 'great wonders and miracles among the people' (Acts 6:8)?","Did you know the gospel reached the temple staff itself: 'a great company of the priests were obedient to the faith' (Acts 6:7)?"],
 questions:[
{q:"What murmuring arose among the disciples?", options:["The Grecians complained that their widows were neglected in the daily ministration","The Hebrews complained about the apostles' teaching","The priests complained about the temple offerings","The Romans complained about the crowds in the temple"], a:0, ref:"Acts 6:1",verse:"And in those days, when the number of the disciples was multiplied, there arose a murmuring of the Grecians against the Hebrews, because their widows were neglected in the daily ministration.", insight:"Growth brings friction; the first church met its first complaint and answered it with order, not offense."},
{q:"In what service were the widows neglected?", options:["The daily ministration","The temple sacrifices","The evening prayers","The offerings of the rich"], a:0, ref:"Acts 6:1",verse:"And in those days, when the number of the disciples was multiplied, there arose a murmuring of the Grecians against the Hebrews, because their widows were neglected in the daily ministration.", insight:"Daily care for widows was the church's work from the start; mercy is never a side project."},
{q:"What did the twelve say it was not reason for them to do?", options:["Leave the word of God, and serve tables","Preach to the Gentiles","Pray in the temple courts","Collect the offerings"], a:0, ref:"Acts 6:2",verse:"Then the twelve called the multitude of the disciples unto them, and said, It is not reason that we should leave the word of God, and serve tables.", insight:"Not every good work is your work; knowing your calling protects the ministry only you can do."},
{q:"How many men were the brethren to look out from among them?", options:["Seven","Twelve","Three","Seventy"], a:0, ref:"Acts 6:3",verse:"Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business.", insight:"God solves practical problems with qualified people; the church's first job description asked for character and the Spirit."},
{q:"What three marks were the seven men to carry?", options:["Honest report, full of the Holy Ghost and wisdom","Wealth, learning, and eloquence","Priestly birth, age, and experience","Strength, speed, and courage"], a:0, ref:"Acts 6:3",verse:"Wherefore, brethren, look ye out among you seven men of honest report, full of the Holy Ghost and wisdom, whom we may appoint over this business.", insight:"Character, Spirit, and wisdom; the first hiring standard of the church still works."},
{q:"To what would the apostles give themselves continually?", options:["Prayer","Journeys to the nations","Building meeting houses","Writing letters"], a:0, ref:"Acts 6:4",verse:"But we will give ourselves continually to prayer, and to the ministry of the word.", insight:"Prayer came first, even before preaching; the ministry of the word is fueled on the knees."},
{q:"What ministry would the apostles keep for themselves?", options:["The ministry of the word","The care of the treasury","The healing of the sick","The training of the scribes"], a:0, ref:"Acts 6:4",verse:"But we will give ourselves continually to prayer, and to the ministry of the word.", insight:"They guarded the word the way shepherds guard the flock; teaching was the apostles' first table."},
{q:"Who was named first among the seven?", options:["Stephen, a man full of faith and of the Holy Ghost","Philip the evangelist","Nicolas the proselyte","Prochorus the scribe"], a:0, ref:"Acts 6:5",verse:"And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:", insight:"Stephen's faith put his name first; God promotes the full-hearted."},
{q:"Which of the seven was a proselyte of Antioch?", options:["Nicolas","Timon","Parmenas","Nicanor"], a:0, ref:"Acts 6:5",verse:"And the saying pleased the whole multitude: and they chose Stephen, a man full of faith and of the Holy Ghost, and Philip, and Prochorus, and Nicanor, and Timon, and Parmenas, and Nicolas a proselyte of Antioch:", insight:"A Gentile convert stood among the first servants; the church's table was wide from the beginning."},
{q:"What did the apostles do when the seven were set before them?", options:["They prayed, and laid their hands on them","They sent them to the temple","They gave them silver and gold","They wrote their names in a book"], a:0, ref:"Acts 6:6",verse:"Whom they set before the apostles: and when they had prayed, they laid their hands on them.", insight:"Hands laid on in prayer; service in God's house is appointed, not merely volunteered."},
{q:"What happened to the word of God after the seven were appointed?", options:["It increased, and the disciples multiplied greatly in Jerusalem","It was hidden from the priests","It slowed for a season","It moved at once to Samaria"], a:0, ref:"Acts 6:7",verse:"And the word of God increased; and the number of the disciples multiplied in Jerusalem greatly; and a great company of the priests were obedient to the faith.", insight:"Right order feeds growth; when servants serve and apostles preach, the word multiplies."},
{q:"Who became obedient to the faith in great numbers?", options:["A great company of the priests","The Roman soldiers","The Sadducees","The scribes of the temple"], a:0, ref:"Acts 6:7",verse:"And the word of God increased; and the number of the disciples multiplied in Jerusalem greatly; and a great company of the priests were obedient to the faith.", insight:"Even the priests, the gospel's fiercest opponents, bowed; no heart is past the reach of the word."},
{q:"How is Stephen described as he did wonders and miracles?", options:["Full of faith and power","Full of years and honor","Full of learning and riches","Full of zeal and boldness"], a:0, ref:"Acts 6:8",verse:"And Stephen, full of faith and power, did great wonders and miracles among the people.", insight:"Faith and power travel together; Stephen's miracles flowed from a full heart."},
{q:"Who rose up disputing with Stephen?", options:["Men of the synagogue of the Libertines, and Cyrenians, and Alexandrians, and of Cilicia and of Asia","The chief priests and the elders","The Roman governors","The Pharisees of Jerusalem"], a:0, ref:"Acts 6:9",verse:"Then there arose certain of the synagogue, which is called the synagogue of the Libertines, and Cyrenians, and Alexandrians, and of them of Cilicia and of Asia, disputing with Stephen.", insight:"Five synagogues against one servant, and they could not win; truth needs no majority."},
{q:"Why were they not able to resist Stephen?", options:["They could not resist the wisdom and the spirit by which he spake","He was guarded by Roman soldiers","He refused to answer them","He fled to another city"], a:0, ref:"Acts 6:10",verse:"And they were not able to resist the wisdom and the spirit by which he spake.", insight:"Wisdom and the Spirit are an unbeatable pair; argue with God and you lose."},
{q:"What did the suborned men claim to have heard?", options:["Blasphemous words against Moses, and against God","Plans to burn the temple","Treason against Caesar","Theft from the treasury"], a:0, ref:"Acts 6:11",verse:"Then they suborned men, which said, We have heard him speak blasphemous words against Moses, and against God.", insight:"When truth will not fall, lies are hired; suborned witnesses are the oldest weapon against the righteous."},
{q:"Whom did they stir up, and where did they bring Stephen?", options:["The people, the elders, and the scribes; they brought him to the council","The Romans; they brought him to the governor","The priests; they brought him to the temple","The merchants; they brought him to the marketplace"], a:0, ref:"Acts 6:12",verse:"And they stirred up the people, and the elders, and the scribes, and came upon him, and caught him, and brought him to the council,", insight:"Stirred-up crowds do the enemy's errands; Stephen stood calm before the council they dragged him to."},
{q:"What did the false witnesses say Stephen never ceased to speak against?", options:["This holy place, and the law","The Roman emperor","The city of Jerusalem","The appointed feasts"], a:0, ref:"Acts 6:13",verse:"And set up false witnesses, which said, This man ceaseth not to speak blasphemous words against this holy place, and the law:", insight:"False witnesses twist devotion into crime; loving God's house was charged as hating it."},
{q:"What did they claim this Jesus of Nazareth would do?", options:["Destroy this place, and change the customs which Moses delivered","Build a new temple of gold","Crown Himself king in Rome","Abolish all the feasts"], a:0, ref:"Acts 6:14",verse:"For we have heard him say, that this Jesus of Nazareth shall destroy this place, and shall change the customs which Moses delivered us.", insight:"They feared a destroyer and missed the builder; Christ came to fulfill, not to wreck."},
{q:"What did the council see when they looked stedfastly on Stephen?", options:["His face as it had been the face of an angel","Tears running down his cheeks","A look of terror","A hardened, angry stare"], a:0, ref:"Acts 6:15",verse:"And all that sat in the council, looking stedfastly on him, saw his face as it had been the face of an angel.", insight:"An angel's face on a man accused of blasphemy; heaven was already testifying for Stephen."}
]},
{n:7, name:"Stephen's Defense", seal:{ref:"Acts 7:59",verse:"And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit."},
 facts:["Did you know Stephen's defense is the longest speech in Acts, a sweep from Abraham to the prophets, and his hearers stopped their ears before he could finish it (Acts 7:57)?","Did you know Stephen charged Israel with carrying 'the tabernacle of Moloch, and the star of your god Remphan,' idols they worshiped even in the wilderness (Acts 7:43)?","Did you know Saul of Tarsus first appears in Scripture holding the clothes of Stephen's killers, a young man consenting to a murder (Acts 7:58)?"],
 questions:[
{q:"Where did the God of glory appear to Abraham?", options:["In Mesopotamia, before he dwelt in Charran","In Canaan, by the oaks of Mamre","In Egypt, by the river Nile","In Haran, at his father's tent"], a:0, ref:"Acts 7:2",verse:"And he said, Men, brethren, and fathers, hearken; The God of glory appeared unto our father Abraham, when he was in Mesopotamia, before he dwelt in Charran,", insight:"God found Abraham in Mesopotamia, far from the promised land; He calls you where you are, not where you wish you were."},
{q:"How much of the promised land did Abraham himself own?", options:["None, not so much as to set his foot on","The field of Machpelah only","The whole hill country","Half of Canaan"], a:0, ref:"Acts 7:5",verse:"And he gave him none inheritance in it, no, not so much as to set his foot on: yet he promised that he would give it to him for a possession, and to his seed after him, when as yet he had no child.", insight:"Not a foot of ground, yet a promise as wide as the sky; faith holds title deeds that heaven honors."},
{q:"How long would Abraham's seed be in bondage in a strange land?", options:["Four hundred years","Seventy years","Forty years","Twelve years"], a:0, ref:"Acts 7:6",verse:"And God spake on this wise, That his seed should sojourn in a strange land; and that they should bring them into bondage, and entreat them evil four hundred years.", insight:"Four hundred years of bondage was in the promise too; God tells the hard part up front and keeps the rescue on time."},
{q:"What covenant did God give Abraham, and when was Isaac circumcised?", options:["The covenant of circumcision; Isaac was circumcised the eighth day","The covenant of salt; Isaac at forty days","The covenant of the rainbow; Isaac at one year","The covenant of the Sabbath; Isaac at twelve years"], a:0, ref:"Acts 7:8",verse:"And he gave him the covenant of circumcision: and so Abraham begat Isaac, and circumcised him the eighth day; and Isaac begat Jacob; and Jacob begat the twelve patriarchs.", insight:"The eighth day marked every son; God seals His promises in flesh and family."},
{q:"Why did the patriarchs sell Joseph into Egypt?", options:["Moved with envy; but God was with him","For thirty pieces of silver; but they soon regretted it","By Pharaoh's command; but he escaped","To pay a family debt; but he was ransomed"], a:0, ref:"Acts 7:9",verse:"And the patriarchs, moved with envy, sold Joseph into Egypt: but God was with him,", insight:"Envy sold him; God kept him. Men write the betrayal, God writes the ending."},
{q:"What did Joseph receive in Pharaoh's sight, and what office followed?", options:["Favour and wisdom; he was made governor over Egypt and all his house","Gold and chariots; he was made captain of the guard","Land and servants; he was made priest of On","A new name; he was made keeper of the prison"], a:0, ref:"Acts 7:10",verse:"And delivered him out of all his afflictions, and gave him favour and wisdom in the sight of Pharaoh king of Egypt; and he made him governor over Egypt and all his house.", insight:"Favour and wisdom came before office; God prepares the man before He promotes him."},
{q:"What changed in Egypt when another king arose?", options:["A king arose which knew not Joseph","Joseph was made a god of Egypt","The Hebrews were set free","The Nile failed for seven years"], a:0, ref:"Acts 7:18",verse:"Till another king arose, which knew not Joseph.", insight:"Gratitude has a short memory in palaces; never anchor your future to a king's favor."},
{q:"How is Moses described at his birth, and how long was he hidden?", options:["Exceeding fair; nourished up in his father's house three months","A strong child; hidden a full year","A quiet baby; hidden forty days","Born in Goshen; hidden seven months"], a:0, ref:"Acts 7:20",verse:"In which time Moses was born, and was exceeding fair, and nourished up in his father’s house three months:", insight:"'Exceeding fair' in God's eyes, not only his mother's; heaven marks its deliverers early."},
{q:"How old was Moses when it came into his heart to visit his brethren?", options:["Full forty years old","Thirty years old","Eighty years old","Twenty years old"], a:0, ref:"Acts 7:23",verse:"And when he was full forty years old, it came into his heart to visit his brethren the children of Israel.", insight:"Forty years in the palace, and his heart still turned to his people; calling outlasts comfort."},
{q:"What appeared to Moses in the wilderness of mount Sina?", options:["An angel of the Lord in a flame of fire in a bush","A pillar of cloud by day","A bright star over the mountain","A whirlwind of dust"], a:0, ref:"Acts 7:30",verse:"And when forty years were expired, there appeared to him in the wilderness of mount Sina an angel of the Lord in a flame of fire in a bush.", insight:"Forty years of tending sheep, then fire in a bush; God is never late to the wilderness."},
{q:"What was Moses commanded at the bush, and why?", options:["Put off his shoes, for the place was holy ground","Wash his hands, for the water was blessed","Cover his face, for the light was blinding","Kneel down, for the angel was mighty"], a:0, ref:"Acts 7:33",verse:"Then said the Lord to him, Put off thy shoes from thy feet: for the place where thou standest is holy ground.", insight:"Holy ground asks for bare feet; reverence is the first lesson of every calling."},
{q:"What did Moses prophesy about a coming prophet?", options:["The Lord would raise up a prophet of their brethren, like unto him","A king would rise from Judah forever","A priest would build a greater temple","A star would rise out of Jacob"], a:0, ref:"Acts 7:37",verse:"This is that Moses, which said unto the children of Israel, A prophet shall the Lord your God raise up unto you of your brethren, like unto me; him shall ye hear.", insight:"Moses pointed past himself; the greatest prophets always point to a greater one."},
{q:"What did Israel make in the wilderness, and how did they celebrate it?", options:["A calf, to which they offered sacrifice and rejoiced in the works of their own hands","A golden crown for Aaron","An altar of brass for the tabernacle","A pillar of stone for Moses"], a:0, ref:"Acts 7:41",verse:"And they made a calf in those days, and offered sacrifice unto the idol, and rejoiced in the works of their own hands.", insight:"They rejoiced in the works of their own hands; idolatry is worship with the mirror turned inward."},
{q:"Where does the most High NOT dwell?", options:["In temples made with hands","In the praises of His people","In heaven above","In a humble and contrite heart"], a:0, ref:"Acts 7:48",verse:"Howbeit the most High dwelleth not in temples made with hands; as saith the prophet,", insight:"No building can house Him; even Solomon's temple was a footstool, not a cage."},
{q:"What did Stephen call his hearers?", options:["Stiffnecked and uncircumcised in heart and ears","Blind and deaf without hope","Fools and slow of heart","Hypocrites and vipers"], a:0, ref:"Acts 7:51",verse:"Ye stiffnecked and uncircumcised in heart and ears, ye do always resist the Holy Ghost: as your fathers did, so do ye.", insight:"Stiff necks and closed ears; Stephen named the disease because he loved the patient."},
{q:"Of what did Stephen accuse his hearers concerning the Just One?", options:["They had become His betrayers and murderers","They had denied Him before Pilate","They had sold Him for silver","They had crowned Him with thorns"], a:0, ref:"Acts 7:52",verse:"Which of the prophets have not your fathers persecuted? and they have slain them which shewed before of the coming of the Just One; of whom ye have been now the betrayers and murderers:", insight:"Betrayers and murderers; the charge was true, and the truth is what got him killed."},
{q:"What did Stephen say he saw?", options:["The heavens opened, and the Son of man standing on the right hand of God","Angels descending upon a ladder","The temple filled with glory","Moses and Elias in bright light"], a:0, ref:"Acts 7:56",verse:"And said, Behold, I see the heavens opened, and the Son of man standing on the right hand of God.", insight:"Jesus standing, not sitting, to welcome His witness; heaven rises for its martyrs."},
{q:"At whose feet did the witnesses lay down their clothes?", options:["A young man's, whose name was Saul","The high priest's","Stephen's brother's","The Roman captain's"], a:0, ref:"Acts 7:58",verse:"And cast him out of the city, and stoned him: and the witnesses laid down their clothes at a young man’s feet, whose name was Saul.", insight:"Saul held the coats while the stones flew; the church's fiercest enemy stood in the martyr's shadow."},
{q:"What were Stephen's last words to the Lord Jesus?", options:["Lord Jesus, receive my spirit","Father, into thy hands I commend","My God, why hast thou forsaken me","Lord, remember me"], a:0, ref:"Acts 7:59",verse:"And they stoned Stephen, calling upon God, and saying, Lord Jesus, receive my spirit.", insight:"He prayed to Jesus as to God; the first martyr died calling on the Lord he had served."},
{q:"What did Stephen cry with a loud voice before he fell asleep?", options:["Lord, lay not this sin to their charge","Lord, avenge my blood","Lord, send thy angels","Lord, judge them righteously"], a:0, ref:"Acts 7:60",verse:"And he kneeled down, and cried with a loud voice, Lord, lay not this sin to their charge. And when he had said this, he fell asleep.", insight:"Forgiveness was his final breath; Stephen died praying the way his Master prayed."}
]},
{n:8, name:"Philip in Samaria", seal:{ref:"Acts 8:37",verse:"And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God."},
 facts:["Did you know the first missionary journey in Acts was forced? Persecution scattered the believers, and 'they that were scattered abroad went every where preaching the word' (Acts 8:4).","Did you know Simon's sin named a sin? 'Simony' is the church's old word for buying spiritual office, from Simon offering money for the Spirit's power (Acts 8:18-20).","Did you know the Ethiopian eunuch was reading Isaiah 53, the suffering servant passage, when Philip climbed into his chariot (Acts 8:32-33)?"],
 questions:[
{q:"Who consented to Stephen's death, and what followed?", options:["Saul; a great persecution scattered the church through Judaea and Samaria","The high priest; the temple was shut for a month","Pilate; the whole city rioted","Herod; the apostles fled to Galilee"], a:0, ref:"Acts 8:1",verse:"And Saul was consenting unto his death. And at that time there was a great persecution against the church which was at Jerusalem; and they were all scattered abroad throughout the regions of Judaea and Samaria, except the apostles.", insight:"Saul consented, and persecution scattered the seed; the enemy's wind only spread the gospel farther."},
{q:"How did Saul make havoc of the church?", options:["Entering into every house, and haling men and women to prison","Burning the meeting places","Bribing the disciples to deny Christ","Driving them out of Jerusalem with soldiers"], a:0, ref:"Acts 8:3",verse:"As for Saul, he made havock of the church, entering into every house, and haling men and women committed them to prison.", insight:"House to house, men and women; persecution is thorough, but it cannot reach the word."},
{q:"What did the scattered believers do everywhere they went?", options:["They preached the word","They hid in the caves","They returned to their trades","They waited for the apostles"], a:0, ref:"Acts 8:4",verse:"Therefore they that were scattered abroad went every where preaching the word.", insight:"Scattered abroad, preaching everywhere; exile became evangelism."},
{q:"Where did Philip go, and what did he preach?", options:["To the city of Samaria; he preached Christ unto them","To Damascus; he preached the law","To Caesarea; he preached to the soldiers","To Joppa; he preached to the fishermen"], a:0, ref:"Acts 8:5",verse:"Then Philip went down to the city of Samaria, and preached Christ unto them.", insight:"Philip took Christ to Samaria, the town Jews avoided; the gospel loves the roads we skip."},
{q:"What miracles marked Philip's preaching?", options:["Unclean spirits came out crying, and many taken with palsies, and the lame, were healed","The dead were raised in the streets","Fire fell from heaven","The sick were healed by his shadow"], a:0, ref:"Acts 8:7",verse:"For unclean spirits, crying with loud voice, came out of many that were possessed with them: and many taken with palsies, and that were lame, were healed.", insight:"Loud demons out, lame legs healed; power backs up preaching that honors Christ."},
{q:"What was the result in that city?", options:["Great joy","Great fear","Great confusion","Great silence"], a:0, ref:"Acts 8:8",verse:"And there was great joy in that city.", insight:"Great joy in that city; where Christ is truly preached, joy is the fruit."},
{q:"Who was Simon, and what had he done in Samaria?", options:["A sorcerer who bewitched the people, giving out that himself was some great one","A priest who taught the law of Moses","A merchant who funded the synagogue","A soldier who guarded the city gates"], a:0, ref:"Acts 8:9",verse:"But there was a certain man, called Simon, which beforetime in the same city used sorcery, and bewitched the people of Samaria, giving out that himself was some great one:", insight:"Simon sold wonder and bought worship; beware the great ones who advertise themselves."},
{q:"What did all the people say of Simon?", options:["This man is the great power of God","This man is a prophet of the Lord","This man is the king's counselor","This man is a teacher of wisdom"], a:0, ref:"Acts 8:10",verse:"To whom they all gave heed, from the least to the greatest, saying, This man is the great power of God.", insight:"From the least to the greatest they called him God's power; crowds can crown a counterfeit."},
{q:"What happened to Simon himself?", options:["He believed also, was baptized, and continued with Philip, wondering at the miracles","He fled the city in fear","He challenged Philip to a contest","He bribed the apostles"], a:0, ref:"Acts 8:13",verse:"Then Simon himself believed also: and when he was baptized, he continued with Philip, and wondered, beholding the miracles and signs which were done.", insight:"Even Simon believed and was baptized; the gospel reaches the bewitched and the bewitchers."},
{q:"Whom did the Jerusalem apostles send to Samaria?", options:["Peter and John","James and Andrew","Barnabas and Saul","Matthew and Thomas"], a:0, ref:"Acts 8:14",verse:"Now when the apostles which were at Jerusalem heard that Samaria had received the word of God, they sent unto them Peter and John:", insight:"Jerusalem sent its best to bless Samaria; true leaders rejoice in another's harvest."},
{q:"How did the Samaritans receive the Holy Ghost?", options:["Peter and John laid their hands on them","Philip baptized them a second time","An angel breathed upon them","They fasted forty days"], a:0, ref:"Acts 8:17",verse:"Then laid they their hands on them, and they received the Holy Ghost.", insight:"Hands laid on, Spirit given; God ties His gifts to His people's touch."},
{q:"What did Simon ask to buy?", options:["This power, that on whomsoever he laid hands, they might receive the Holy Ghost","A seat among the apostles","The gift of tongues for himself","Pardon for his sorceries"], a:0, ref:"Acts 8:19",verse:"Saying, Give me also this power, that on whomsoever I lay hands, he may receive the Holy Ghost.", insight:"'Give me also this power'; he wanted the gift without the Giver, the power without the purity."},
{q:"How did Peter answer Simon's offer of money?", options:["Thy money perish with thee","Take thy silver and go","Keep thy money for the poor","Bring more, and we shall see"], a:0, ref:"Acts 8:20",verse:"But Peter said unto him, Thy money perish with thee, because thou hast thought that the gift of God may be purchased with money.", insight:"'Thy money perish with thee'; some things cannot be bought, and grace leads the list."},
{q:"How did Peter describe Simon's spiritual state?", options:["In the gall of bitterness, and in the bond of iniquity","In the shadow of death","In the snare of the devil","In the valley of trouble"], a:0, ref:"Acts 8:23",verse:"For I perceive that thou art in the gall of bitterness, and in the bond of iniquity.", insight:"Gall of bitterness, bond of iniquity; sin pickles the heart and chains the will."},
{q:"Where did the angel of the Lord send Philip?", options:["Toward the south, to the way from Jerusalem to Gaza, which is desert","Toward the north, to Damascus","Toward the sea, to Joppa","Toward the east, to Jericho"], a:0, ref:"Acts 8:26",verse:"And the angel of the Lord spake unto Philip, saying, Arise, and go toward the south unto the way that goeth down from Jerusalem unto Gaza, which is desert.", insight:"A desert road for one seeking soul; God sends His best evangelists down empty highways."},
{q:"Who was the Ethiopian eunuch?", options:["A man of great authority under Candace, in charge of all her treasure, who had come to Jerusalem to worship","A merchant of Ethiopia trading in spices","A soldier guarding the queen's palace","A priest of the Ethiopian temple"], a:0, ref:"Acts 8:27",verse:"And he arose and went: and, behold, a man of Ethiopia, an eunuch of great authority under Candace queen of the Ethiopians, who had the charge of all her treasure, and had come to Jerusalem for to worship,", insight:"Treasurer of a queen, yet hungry for God; all the gold of Ethiopia could not buy what he sought in Jerusalem."},
{q:"How did the eunuch answer Philip's question?", options:["How can I, except some man should guide me?","I read only the Psalms","The prophet speaks of himself","I need no teacher"], a:0, ref:"Acts 8:31",verse:"And he said, How can I, except some man should guide me? And he desired Philip that he would come up and sit with him.", insight:"'How can I, except some man should guide me?' Honest hunger asks for help; pride reads on alone."},
{q:"What did Philip do, beginning at that same scripture?", options:["He preached unto him Jesus","He taught him the law of Moses","He warned him of coming judgment","He told him to return to Ethiopia"], a:0, ref:"Acts 8:35",verse:"Then Philip opened his mouth, and began at the same scripture, and preached unto him Jesus.", insight:"Beginning at the same scripture; every road in the Bible leads to Jesus if you read it right."},
{q:"What did the eunuch confess before his baptism?", options:["I believe that Jesus Christ is the Son of God","I believe the prophets spoke truly","I believe Philip is sent from God","I believe in the God of Israel"], a:0, ref:"Acts 8:37",verse:"And Philip said, If thou believest with all thine heart, thou mayest. And he answered and said, I believe that Jesus Christ is the Son of God.", insight:"The whole gospel in one sentence; belief with all the heart opens the water."},
{q:"What happened after the baptism?", options:["The Spirit of the Lord caught away Philip, and the eunuch went on his way rejoicing","Philip stayed behind to teach him","They traveled together to Ethiopia","The chariot broke down on the road"], a:0, ref:"Acts 8:39",verse:"And when they were come up out of the water, the Spirit of the Lord caught away Philip, that the eunuch saw him no more: and he went on his way rejoicing.", insight:"Philip vanished, joy remained; the evangelist left, but the rejoicing stayed with the convert."}
]},
{n:9, name:"Saul's Conversion", seal:{ref:"Acts 9:15",verse:"But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:"},
 facts:["Did you know Saul's hunting license was paperwork? He asked the high priest for 'letters to Damascus' so he could drag believers back bound, and the light of heaven tore up his plans on the road (Acts 9:2-3).","Did you know Jesus gave Ananias Paul's whole life mission in one sentence: 'a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel' (Acts 9:15)?","Did you know the church's most feared enemy became its most trusted friend through one man's courage? Barnabas took Saul to the apostles when everyone else was afraid (Acts 9:26-27)."],
 questions:[
{q:"How is Saul described as he went to the high priest?", options:["Breathing out threatenings and slaughter against the disciples of the Lord","Weeping over his past sins","Seeking wisdom from the elders","Carrying letters of peace"], a:0, ref:"Acts 9:1",verse:"And Saul, yet breathing out threatenings and slaughter against the disciples of the Lord, went unto the high priest,", insight:"Breathing threatenings and slaughter; hatred was his very breath until grace stopped him in his tracks."},
{q:"What did Saul desire of the high priest?", options:["Letters to Damascus, that he might bring bound to Jerusalem any of this way","Permission to preach in the synagogues","Money for his long journey","Soldiers to guard him on the road"], a:0, ref:"Acts 9:2",verse:"And desired of him letters to Damascus to the synagogues, that if he found any of this way, whether they were men or women, he might bring them bound unto Jerusalem.", insight:"'This way' was the church's first nickname; Saul hunted the Way before he ever walked it."},
{q:"What did the voice from heaven say to Saul?", options:["Saul, Saul, why persecutest thou me?","Saul, Saul, where goest thou?","Saul, Saul, hear my law","Saul, Saul, turn back now"], a:0, ref:"Acts 9:4",verse:"And he fell to the earth, and heard a voice saying unto him, Saul, Saul, why persecutest thou me?", insight:"Persecuting the church is persecuting Christ; He takes the blows aimed at His people personally."},
{q:"Who did the voice say He was?", options:["I am Jesus whom thou persecutest","I am the God of thy fathers","I am an angel of the Lord","I am the prophet thou seekest"], a:0, ref:"Acts 9:5",verse:"And he said, Who art thou, Lord? And the Lord said, I am Jesus whom thou persecutest: it is hard for thee to kick against the pricks.", insight:"'I am Jesus'; the name Saul hated most was the name that stopped him on the road."},
{q:"What did the trembling Saul ask?", options:["Lord, what wilt thou have me to do?","Lord, why hast thou struck me?","Lord, spare my life","Lord, send me safely home"], a:0, ref:"Acts 9:6",verse:"And he trembling and astonished said, Lord, what wilt thou have me to do? And the Lord said unto him, Arise, and go into the city, and it shall be told thee what thou must do.", insight:"The persecutor's first prayer was surrender; 'what wilt thou have me to do' is where every calling begins."},
{q:"What was Saul's condition for three days in Damascus?", options:["Without sight, and neither did eat nor drink","Feverish and calling out in pain","Bound in chains in a cell","Hidden in a friend's upper room"], a:0, ref:"Acts 9:9",verse:"And he was three days without sight, and neither did eat nor drink.", insight:"Three days blind and fasting; the mighty hunter sat in darkness until God gave him new eyes."},
{q:"What did the Lord tell Ananias about the man on Straight street?", options:["That Saul of Tarsus was in the house of Judas, and behold, he prayeth","That a prophet waited there to anoint him","That soldiers guarded the house","That the house stood empty"], a:0, ref:"Acts 9:11",verse:"And the Lord said unto him, Arise, and go into the street which is called Straight, and enquire in the house of Judas for one called Saul, of Tarsus: for, behold, he prayeth,", insight:"Straight street, and Saul praying; the proud Pharisee was on his knees at last."},
{q:"What had Ananias heard about Saul?", options:["How much evil he had done to the saints at Jerusalem","That he was a Roman citizen","That he had studied under Gamaliel","That he was coming to preach"], a:0, ref:"Acts 9:13",verse:"Then Ananias answered, Lord, I have heard by many of this man, how much evil he hath done to thy saints at Jerusalem:", insight:"Ananias knew Saul's record; God knew his future. Obedience walks past the reputation."},
{q:"What did the Lord call Saul?", options:["A chosen vessel, to bear His name before the Gentiles, and kings, and the children of Israel","A faithful servant of the synagogue","A new high priest for the people","A scribe of the law"], a:0, ref:"Acts 9:15",verse:"But the Lord said unto him, Go thy way: for he is a chosen vessel unto me, to bear my name before the Gentiles, and kings, and the children of Israel:", insight:"A chosen vessel; God picks the unlikeliest jars to carry His name to kings."},
{q:"What did the Lord say He would show Saul?", options:["How great things he must suffer for His name's sake","The riches of the kingdom","The end of the age","The names of the twelve apostles"], a:0, ref:"Acts 9:16",verse:"For I will shew him how great things he must suffer for my name’s sake.", insight:"Suffering was in the job description; the call to glory always includes the cross."},
{q:"How did Ananias greet Saul, and what did he promise?", options:["Brother Saul; that he might receive his sight, and be filled with the Holy Ghost","Master Saul; that he would be healed","Friend; that he would be kept safe","Rabbi; that he would be taught"], a:0, ref:"Acts 9:17",verse:"And Ananias went his way, and entered into the house; and putting his hands on him said, Brother Saul, the Lord, even Jesus, that appeared unto thee in the way as thou camest, hath sent me, that thou mightest receive thy sight, and be filled with the Holy Ghost.", insight:"'Brother Saul'; one word of grace turned an enemy into family before the scales fell."},
{q:"What happened when Ananias laid his hands on him?", options:["Scales fell from his eyes, he received sight forthwith, and was baptized","He spoke in tongues at once","He fell into a deep sleep","He was taken up to heaven"], a:0, ref:"Acts 9:18",verse:"And immediately there fell from his eyes as it had been scales: and he received sight forthwith, and arose, and was baptized.", insight:"Scales fell, sight returned, baptism followed; grace works fast when the heart is ready."},
{q:"What did Saul preach straightway in the synagogues?", options:["Christ, that he is the Son of God","The law of Moses","Repentance only","The traditions of the elders"], a:0, ref:"Acts 9:20",verse:"And straightway he preached Christ in the synagogues, that he is the Son of God.", insight:"Straightway he preached; a true conversion cannot wait to speak."},
{q:"Why were all that heard him amazed?", options:["Is not this he that destroyed them which called on this name in Jerusalem?","They had never heard such learning","He spoke in their own tongue","He performed miracles before them"], a:0, ref:"Acts 9:21",verse:"But all that heard him were amazed, and said; Is not this he that destroyed them which called on this name in Jerusalem, and came hither for that intent, that he might bring them bound unto the chief priests?", insight:"The destroyer turned preacher; nobody's past is louder than God's grace."},
{q:"How did Saul answer the Jews at Damascus?", options:["He increased in strength, and confounded them, proving that this is very Christ","He debated philosophy with them","He paid them to keep silent","He left the city at once"], a:0, ref:"Acts 9:22",verse:"But Saul increased the more in strength, and confounded the Jews which dwelt at Damascus, proving that this is very Christ.", insight:"He proved 'this is very Christ'; the fiercest opponent makes the strongest witness."},
{q:"How did the disciples save Saul from the Jews who watched the gates?", options:["They took him by night, and let him down by the wall in a basket","They hid him in the synagogue","They disguised him as a merchant","They bribed the gatekeepers"], a:0, ref:"Acts 9:25",verse:"Then the disciples took him by night, and let him down by the wall in a basket.", insight:"The great apostle escaped in a basket; God is not embarrassed by humble exits."},
{q:"Who vouched for Saul when he came to Jerusalem?", options:["Barnabas, who took him and brought him to the apostles","Peter, who had met him before","Ananias, who had healed him","James, the Lord's brother"], a:0, ref:"Acts 9:27",verse:"But Barnabas took him, and brought him to the apostles, and declared unto them how he had seen the Lord in the way, and that he had spoken to him, and how he had preached boldly at Damascus in the name of Jesus.", insight:"Barnabas, the son of encouragement, risked his name for Saul; every convert needs someone who believes first."},
{q:"What was the state of the churches after these things?", options:["They had rest, were edified, walked in the fear of the Lord, and were multiplied","They were scattered once again","They argued over doctrine","They returned to the temple"], a:0, ref:"Acts 9:31",verse:"Then had the churches rest throughout all Judaea and Galilee and Samaria, and were edified; and walking in the fear of the Lord, and in the comfort of the Holy Ghost, were multiplied.", insight:"Rest, edifying, and multiplying; when the persecutor converts, the church can breathe."},
{q:"Who was Tabitha, also called Dorcas?", options:["A disciple at Joppa, full of good works and almsdeeds which she did","A prophetess at Jerusalem","A widow of Lydda","A servant in Peter's company"], a:0, ref:"Acts 9:36",verse:"Now there was at Joppa a certain disciple named Tabitha, which by interpretation is called Dorcas: this woman was full of good works and almsdeeds which she did.", insight:"Full of good works and almsdeeds; her whole biography is one line, and it is beautiful."},
{q:"What did Peter say to the dead Tabitha?", options:["Tabitha, arise","Woman, live again","In Jesus' name, breathe","Daughter, return to us"], a:0, ref:"Acts 9:40",verse:"But Peter put them all forth, and kneeled down, and prayed; and turning him to the body said, Tabitha, arise. And she opened her eyes: and when she saw Peter, she sat up.", insight:"'Tabitha, arise'; Peter prayed first, then spoke, and death obeyed the order."}
]},
{n:10, name:"Peter and Cornelius", seal:{ref:"Acts 10:34",verse:"Then Peter opened his mouth, and said, Of a truth I perceive that God is no respecter of persons:"},
 facts:["Did you know Cornelius was the first full Gentile household brought into the church, a Roman centurion whose prayers and alms God remembered (Acts 10:1-4)?","Did you know Peter's vision came while he was hungry? He went up to pray at noon, 'became very hungry,' and fell into a trance while lunch was being made ready (Acts 10:9-10).","Did you know the Jewish believers with Peter were 'astonished' when the Holy Ghost fell on Gentiles, because they heard them 'speak with tongues, and magnify God' just as at Pentecost (Acts 10:45-46)?"],
 questions:[
{q:"Who was Cornelius?", options:["A centurion of the band called the Italian band, in Caesarea","A priest of the Jerusalem temple","A merchant of Joppa","A scribe of the Sanhedrin"], a:0, ref:"Acts 10:1",verse:"There was a certain man in Caesarea called Cornelius, a centurion of the band called the Italian band,", insight:"A Roman officer in Caesarea; the gospel was about to march into a Gentile barracks."},
{q:"How is Cornelius described?", options:["Devout, fearing God with all his house, giving much alms, praying to God alway","Rich and powerful, feared by all","Learned in the law, strict in tradition","A seeker of signs and wonders"], a:0, ref:"Acts 10:2",verse:"A devout man, and one that feared God with all his house, which gave much alms to the people, and prayed to God alway.", insight:"Devout with his whole house, generous and prayerful; God notices Gentile goodness too."},
{q:"What did the angel say about Cornelius's prayers and alms?", options:["They are come up for a memorial before God","They were heard in the temple","They pleased the high priest","They had earned him salvation"], a:0, ref:"Acts 10:4",verse:"And when he looked on him, he was afraid, and said, What is it, Lord? And he said unto him, Thy prayers and thine alms are come up for a memorial before God.", insight:"Prayers and alms rose as a memorial; heaven keeps books on quiet faithfulness."},
{q:"Where was Peter lodging, according to the angel?", options:["With one Simon a tanner, whose house is by the sea side","In the upper room at Jerusalem","With Cornelius's own servants","In the house of Mary"], a:0, ref:"Acts 10:6",verse:"He lodgeth with one Simon a tanner, whose house is by the sea side: he shall tell thee what thou oughtest to do.", insight:"A tanner's house by the sea; God gives street addresses when He wants you found."},
{q:"Where and when did Peter go up to pray?", options:["Upon the housetop, about the sixth hour","In the temple, at the ninth hour","By the sea, at sunrise","In the upper room, at midnight"], a:0, ref:"Acts 10:9",verse:"On the morrow, as they went on their journey, and drew nigh unto the city, Peter went up upon the housetop to pray about the sixth hour:", insight:"The housetop at noon; God interrupts ordinary prayer with extraordinary vision."},
{q:"What did Peter see descending from heaven?", options:["A great sheet knit at the four corners, let down to the earth","A ladder reaching to heaven","A cloud of angels","A scroll sealed with seven seals"], a:0, ref:"Acts 10:11",verse:"And saw heaven opened, and a certain vessel descending unto him, as it had been a great sheet knit at the four corners, and let down to the earth:", insight:"A sheet knit at the four corners; the whole world of creatures came down in one bundle."},
{q:"What was in the sheet?", options:["All manner of fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air","Only clean animals","Fish of the sea","Bread and wine"], a:0, ref:"Acts 10:12",verse:"Wherein were all manner of fourfooted beasts of the earth, and wild beasts, and creeping things, and fowls of the air.", insight:"Every creature, clean and unclean together; God's menu was bigger than Peter's."},
{q:"How did Peter answer the voice that said, 'Rise, Peter; kill, and eat'?", options:["Not so, Lord; I have never eaten any thing that is common or unclean","Yes, Lord, at once","What meaneth this vision?","Let me call the others first"], a:0, ref:"Acts 10:14",verse:"But Peter said, Not so, Lord; for I have never eaten any thing that is common or unclean.", insight:"'Not so, Lord' is a contradiction; you cannot refuse Him and still call Him Lord."},
{q:"What did the voice speak the second time?", options:["What God hath cleansed, that call not thou common","Eat, and ask no questions","The law is now abolished","Go to Cornelius at once"], a:0, ref:"Acts 10:15",verse:"And the voice spake unto him again the second time, What God hath cleansed, that call not thou common.", insight:"What God hath cleansed; heaven, not habit, decides what is clean."},
{q:"How many times was this done?", options:["Thrice","Once","Seven times","Forty times"], a:0, ref:"Acts 10:16",verse:"This was done thrice: and the vessel was received up again into heaven.", insight:"Thrice, like Peter's three denials undone; God repeats the lesson until it lands."},
{q:"What did the Spirit tell Peter about the men seeking him?", options:["Arise, get thee down, and go with them, doubting nothing, for I have sent them","Send them away at once","Preach to them from the roof","Ask them for money"], a:0, ref:"Acts 10:20",verse:"Arise therefore, and get thee down, and go with them, doubting nothing: for I have sent them.", insight:"'Doubting nothing'; when God sends, second-guessing is disobedience."},
{q:"How did the messengers describe Cornelius?", options:["A just man, fearing God, of good report among all the nation of the Jews, warned from God by an holy angel","A rich man seeking healing","A soldier wanting promotion","A priest seeking the truth"], a:0, ref:"Acts 10:22",verse:"And they said, Cornelius the centurion, a just man, and one that feareth God, and of good report among all the nation of the Jews, was warned from God by an holy angel to send for thee into his house, and to hear words of thee.", insight:"Just, God-fearing, well reported; even the nation that distrusted Gentiles spoke well of him."},
{q:"What did Peter say when Cornelius fell down at his feet to worship him?", options:["Stand up; I myself also am a man","Kneel, for I am holy","Rise, my son","Worship God alone"], a:0, ref:"Acts 10:26",verse:"But Peter took him up, saying, Stand up; I myself also am a man.", insight:"'I myself also am a man'; true apostles refuse worship and point to Christ."},
{q:"What had God showed Peter about men of other nations?", options:["That he should not call any man common or unclean","That Gentiles must keep the law of Moses","That Jews should avoid their company","That the gospel was for Jews only"], a:0, ref:"Acts 10:28",verse:"And he said unto them, Ye know how that it is an unlawful thing for a man that is a Jew to keep company, or come unto one of another nation; but God hath shewed me that I should not call any man common or unclean.", insight:"No man common or unclean; the sheet was about people, not pork."},
{q:"When did Cornelius say the angel appeared to him?", options:["Four days ago, while he was fasting, at the ninth hour of prayer","Last night in a dream","At the temple yesterday","During the Passover feast"], a:0, ref:"Acts 10:30",verse:"And Cornelius said, Four days ago I was fasting until this hour; and at the ninth hour I prayed in my house, and, behold, a man stood before me in bright clothing,", insight:"Four days of fasting, then a bright visitor; God answers the hungry on schedule."},
{q:"What did Peter perceive about God?", options:["Of a truth, God is no respecter of persons","God favors the Jews above all","God dwells only in temples","God hears only the priests"], a:0, ref:"Acts 10:34",verse:"Then Peter opened his mouth, and said, Of a truth I perceive that God is no respecter of persons:", insight:"No respecter of persons; the gospel's guest list has no favorites."},
{q:"How is Jesus described in Peter's sermon?", options:["Anointed with the Holy Ghost and with power, who went about doing good","Crowned king in Jerusalem","A prophet like Moses","A teacher of parables"], a:0, ref:"Acts 10:38",verse:"How God anointed Jesus of Nazareth with the Holy Ghost and with power: who went about doing good, and healing all that were oppressed of the devil; for God was with him.", insight:"Went about doing good; Peter summed up the whole life of Jesus in five words."},
{q:"What did God do on the third day?", options:["He raised Him up, and showed Him openly","He sent Him into Galilee","He crowned Him in heaven","He judged the world"], a:0, ref:"Acts 10:40",verse:"Him God raised up the third day, and shewed him openly;", insight:"Raised up the third day; the resurrection is the sermon every sermon must preach."},
{q:"What happened while Peter yet spake these words?", options:["The Holy Ghost fell on all them which heard the word","The crowd interrupted him","An earthquake shook the house","Cornelius was baptized"], a:0, ref:"Acts 10:44",verse:"While Peter yet spake these words, the Holy Ghost fell on all them which heard the word.", insight:"The Spirit fell mid-sermon; God does not wait for the altar call."},
{q:"What question did Peter ask about baptism?", options:["Can any man forbid water, that these should not be baptized?","Who will go and fetch the water?","Shall we wait for the apostles?","Must they be circumcised first?"], a:0, ref:"Acts 10:47",verse:"Can any man forbid water, that these should not be baptized, which have received the Holy Ghost as well as we?", insight:"'Can any man forbid water?' If God has accepted them, the church must not refuse them."}
]}
]);
